const int K = 31;
const int MOD = int(1e9) + 7;

int k = 0;

struct matr {

    int a[K][K];

    matr() {
        for (int i = 0; i <= k; ++i) {
            for (int j = 0; j <= k; ++j) {
                a[i][j] = 0;
            }
